// ---- calendar name vs service (2026-09-16) ----
// One calendar of 30 carries its service in its NAME: "Dr. Prof. Szekely Attila  - Consiliere /
// Terapie psiho-ortoptica" (note the double space). Returning that whole string as `doctor` made the
// agent read the service suffix out loud, and pass it back into booking. Split it: `doctor` is the
// speakable name, `service` is the suffix, and the name matcher resolves either form to the same
// single calendar (verified against all 30 live names).
const splitName = raw => {
  const s = (raw || '').toString().replace(/\s+/g, ' ').trim();
  const m = s.match(/^(.*?)\s+[-\u2013\u2014]\s+(.*)$/);
  // No `service` key at all when there is no suffix, so 29 of 30 calendars are unchanged.
  return m ? { doctor: m[1].trim(), service: m[2].trim() } : { doctor: s };
};
const q = $('CA Validate Input').first().json;
const resp = $input.first().json;
if (resp.statusCode !== 200 || !resp.body || !resp.body.Calendars) {
  return [{ json: { _error: true, success: false, error: 'evolvo_api_error', step: 'get_info',
    status: resp.statusCode } }];
}
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const STOP = ['dr','dra','doktor','doctor','doamna','domnul','doctorul','doctorita','medic','medicul','doktornő','doktorno','doktor ur','ur','urnő','urno'];
const words = s => norm(s).split(/[^a-z0-9]+/).filter(w => w && !STOP.includes(w));
const lev = (a, b) => { const m = a.length, n = b.length; if (!m) return n; if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) { const cur = [i];
    for (let j = 1; j <= n; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur; }
  return prev[n]; };
// A spoken/ASR name token matches a calendar name token when equal, a prefix (>=3 chars), or within a small edit distance.
const tokEq = (q, t) => q === t || (q.length >= 3 && (t.startsWith(q) || q.startsWith(t))) || (q.length >= 3 && lev(q, t) <= (q.length >= 5 ? 2 : 1));
const nameMatch = (query, name) => { const qw = words(query), nw = words(name); return qw.length > 0 && qw.every(q => nw.some(t => tokEq(q, t))); };
// Provider kind, read off the calendar name as evolvo writes it.
// "Optometrist Bodi Ildiko" -> optometrist. "Dr. Baricz Anna" -> doctor.
// A name carrying a service suffix is a SPECIALTY calendar, not general eye care:
// "Dr. Prof. Szekely Attila  - Consiliere / Terapie psiho-ortoptica" -> vision_therapy.
// Anything unrecognised is treated as a doctor: the safe direction to fail in.
const providerKind = name => {
  const n = norm(name).trim();
  const svc = norm(splitName(name).service);
  if (svc) {
    if (/ortopt/.test(svc)) return 'vision_therapy';
    return 'specialty';
  }
  if (/^optometrist\b/.test(n)) return 'optometrist';
  return 'doctor';
};
// General eye care - what a caller who has not asked for anything specific means.
const GENERAL = ['doctor', 'optometrist'];
const isGeneral = name => GENERAL.includes(providerKind(name));
// A specialty provider is only ever surfaced when the caller asked for one: by naming the person,
// or by sending that exact provider_type. Never as "the earliest free slot at this branch"
// (which is how the psycho-orthoptics calendar became the default answer for Republicii).
const wantsSpecialty = Boolean(q.provider_type) && !GENERAL.includes(q.provider_type);
// City / branch aliases as callers say them (RO, HU, ASR variants) -> how evolvo writes the workstation.
const ALIAS = [[/^(targu|tirgu|tg\.?|tg)\s*mures$/, 'tg. mures'], [/^marosvasarhely$/, 'tg. mures'], [/^mures$/, 'tg. mures'],
  [/^(regin|szaszregen|reghin)$/, 'reghin'], [/^(szovata|sovata)$/, 'sovata'],
  [/^(posta utca|postei|posta)$/, 'postei'], [/^(rozsak tere|trandafirilor)$/, 'trandafirilor'],
  [/^(koztarsasag|szentgyorgyter|republicii)$/, 'republicii'], [/^(dozsa|doja|dozsa gyorgy)$/, 'doja'],
  [/^(bulevard|bulevardul|1 decembrie 1918)$/, '1 dec 1918 nr 49']];
const canonPlace = s => { const n = norm(s).replace(/[^a-z0-9. ]+/g, ' ').replace(/\s+/g, ' ').trim(); for (const [re, to] of ALIAS) if (re.test(n)) return to; return n; };
const placeMatch = (query, ws) => { const qn = canonPlace(query), wn = norm(ws); if (!qn) return true; if (wn.includes(qn)) return true; const qw = words(qn); return qw.length > 0 && qw.every(q => words(ws).some(t => tokEq(q, t))); };
const cals = resp.body.Calendars;
if (!q.doctor && !q.location && !q.city && !wantsSpecialty) {
  return [{ json: { _error: true, success: false, error: 'missing_target',
    message: 'Ask the caller which branch, city or doctor they want before checking availability. Do not guess one.',
    available_locations: [...new Set(cals.map(c => c.workstation))] } }];
}
let m = cals;
let byDoctor = null;
if (q.doctor) { byDoctor = m.filter(c => nameMatch(q.doctor, c.name)); m = byDoctor; }
if (q.city) m = m.filter(c => placeMatch(q.city, c.workstation));
if (q.location) m = m.filter(c => placeMatch(q.location, c.workstation));
if (m.length === 0 && byDoctor && byDoctor.length > 0) {
  return [{ json: { _error: true, success: false, error: 'doctor_not_at_location',
    message: 'This doctor exists but not at the requested branch. Tell the caller where the doctor works and ask whether that branch suits, or offer another doctor at the requested branch; then call again.',
    doctor: [...new Set(byDoctor.map(c => splitName(c.name).doctor))],
    doctor_locations: [...new Set(byDoctor.map(c => c.workstation))],
    doctors_at_requested_location: [...new Set(cals.filter(c => placeMatch(q.location || q.city, c.workstation) && isGeneral(c.name)).map(c => splitName(c.name).doctor))] } }];
}
// ---- specialty gate (2026-09-16) ----
// Drop specialty calendars unless this caller asked for one. Runs before the kind filter and after
// the location filters, so `doctor_not_at_location` still reports the truth about a named person.
if (!q.doctor && !wantsSpecialty) {
  const general = m.filter(c => isGeneral(c.name));
  if (general.length === 0 && m.length > 0) {
    return [{ json: { _error: true, success: false, error: 'only_specialty_providers_here',
      message: 'That branch has no general eye doctor or optometrist - only a specialty provider, who must NOT be offered unless the caller asked for that specific service. Offer another branch instead.',
      requested_location: q.location || q.city || '',
      specialty_providers: [...new Set(m.map(c => splitName(c.name).doctor))],
      specialty_services: [...new Set(m.map(c => splitName(c.name).service).filter(Boolean))],
      other_locations: [...new Set(cals.filter(c => isGeneral(c.name)).map(c => c.workstation))] } }];
  }
  m = general;
}
// Provider-kind filter. Deliberately skipped when the caller named a specific person:
// an explicit request for Dr. X always beats the visit-type heuristic, so a stray
// provider_type alongside a doctor name can never strand the caller.
if (q.provider_type && !q.doctor) {
  const byType = m.filter(c => providerKind(c.name) === q.provider_type);
  if (byType.length === 0 && m.length > 0) {
    return [{ json: { _error: true, success: false, error: 'no_provider_of_type',
      message: 'Nobody of the requested kind works at that branch. Say so plainly, then offer what IS available there and call again.',
      requested_provider_type: q.provider_type,
      requested_location: q.location || q.city || '',
      available_provider_types: [...new Set(m.map(c => providerKind(c.name)))],
      available_doctors: [...new Set(m.filter(c => isGeneral(c.name)).map(c => splitName(c.name).doctor))],
      available_locations: [...new Set(m.map(c => c.workstation))] } }];
  }
  m = byType;
}
if (m.length === 0) {
  return [{ json: { _error: true, success: false, error: 'no_match',
    message: 'No doctor/location matches. Offer the caller these options (at most three at a time) and call again.',
    available_doctors: [...new Set(cals.filter(c => isGeneral(c.name)).map(c => splitName(c.name).doctor))],
    available_locations: [...new Set(cals.map(c => c.workstation))] } }];
}
// A branch alone can match up to ~8 calendars; query them all so `earliest` works for no-preference callers.
if (m.length > 10) {
  return [{ json: { _error: true, success: false, error: 'too_many_matches',
    message: 'Too many calendars match. Ask the caller to narrow down by doctor or location.',
    matching_doctors: [...new Set(m.map(c => splitName(c.name).doctor))],
    matching_locations: [...new Set(m.map(c => c.workstation))] } }];
}
return m.map(c => ({ json: { calendarid: c.calendarid, ...splitName(c.name), location: c.workstation,
  slot_duration: c.slot_duration, provider_type: providerKind(c.name) } }));

// ---- spoken date labels (2026-09-15) ----
// A live call read "2026-09-16 15:40" out as "astazi, marti 15 septembrie" and the next slot
// (2026-09-17 10:00) as "maine, miercuri 16 septembrie" - the LLM was converting ISO dates to
// spoken dates itself and was a day out, twice in one call, weekday name included. It never has to
// do that arithmetic: every date we emit now carries date_spoken (weekday + day + month in
// English, for the agent to translate) and relative_day (today / tomorrow / in N days), so
// speaking a date is a translation, not a calculation.
const _WD = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const _MO = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const _todayISO = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Bucharest' });
const _dayNo = iso => Math.round(Date.parse(iso + 'T12:00:00Z') / 86400000);
function dateLabels(iso) {
  iso = (iso || '').toString().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return {};
  const d = new Date(iso + 'T12:00:00Z');
  const diff = _dayNo(iso) - _dayNo(_todayISO);
  return {
    date_spoken: _WD[d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + _MO[d.getUTCMonth()],
    relative_day: diff === 0 ? 'today' : diff === 1 ? 'tomorrow' : diff === 2 ? 'the day after tomorrow'
      : diff < 0 ? 'IN THE PAST - do not offer this' : 'in ' + diff + ' days',
  };
}
const SPEAK_DATES = 'Never work out a date yourself and never re-read the ISO date: say date_spoken translated into the caller\'s language, and say today or tomorrow only when relative_day says so.';
const cals = $('CA Match Calendars').all();
const resps = $input.all();
const q = $('CA Validate Input').first().json;
const out = [];
let earliest = null;
let requestedDay = null;
for (let i = 0; i < resps.length; i++) {
  const cal = cals[i] ? cals[i].json : {};
  const r = resps[i].json;
  if (r.statusCode !== 200 || !r.body || !r.body.Records) {
    out.push({ doctor: cal.doctor, ...(cal.service ? { service: cal.service } : {}), location: cal.location,
      provider_type: cal.provider_type, error: 'no_availability_data', status: r.statusCode });
    continue;
  }
  const recs = (r.body.Records || []).filter(rec => (rec.free_timespace || []).length > 0);
  const days = recs.slice(0, 4).map(rec => ({
    date: rec.wday,
    ...dateLabels(rec.wday),
    free_times: (rec.free_timespace || []).slice(0, 8).map(s => s.slot),
    total_free_slots: (rec.free_timespace || []).length,
  }));
  for (const rec of recs) {
    const t = (rec.free_timespace || [])[0];
    if (!t) continue;
    const key = rec.wday + ' ' + t.slot;
    if (!earliest || key < earliest.date + ' ' + earliest.time) earliest = { date: rec.wday, ...dateLabels(rec.wday), time: t.slot, doctor: cal.doctor, ...(cal.service ? { service: cal.service } : {}), location: cal.location, provider_type: cal.provider_type };
    if (q.requested_date && rec.wday === q.requested_date) {
      const cand = { date: rec.wday, ...dateLabels(rec.wday), time: t.slot, doctor: cal.doctor, ...(cal.service ? { service: cal.service } : {}), location: cal.location, provider_type: cal.provider_type, free_times: (rec.free_timespace || []).slice(0, 8).map(s => s.slot) };
      if (!requestedDay || cand.time < requestedDay.time) requestedDay = cand;
    }
  }
  out.push({ doctor: cal.doctor, ...(cal.service ? { service: cal.service } : {}), location: cal.location,
    provider_type: cal.provider_type, slot_duration_minutes: cal.slot_duration, available_days: days });
}
const res = { success: true, today: _todayISO, date_searched_from: q.date_from, results: out };
// Echoed only when the filter actually ran; a named doctor bypasses it (see CA Match Calendars).
if (q.provider_type && !q.doctor) res.provider_type_filter = q.provider_type;
if (earliest) res.earliest = earliest;
if (q.requested_date) {
  res.requested_date = q.requested_date;
  res.requested_date_status = requestedDay ? 'available' : 'not_available';
  if (requestedDay) res.requested_date_slots = requestedDay;
}
res.note = 'Times are local Romania time (24h). earliest = the single earliest free slot across all matched calendars; use it for urgent callers or callers with no preference. The system searched the next ~15 working days of each calendar starting from date_searched_from, so nothing here falls before that date and nothing here is today. ' + SPEAK_DATES;
return [{ json: res }];

const b = ($input.first().json.body) || {};
const str = x => (typeof x === 'string' ? x.trim() : '');
const missing = [];
const full_name = str(b.full_name);
const PLACEHOLDER = ['necunoscut','ismeretlen','unknown','n/a','na','-','pacient','patient','beteg'];
if (!full_name || full_name.replace(/[^\p{L}]/gu, '').length < 2 || PLACEHOLDER.includes(full_name.toLowerCase())) missing.push('full_name (real full name, never empty or a placeholder)');
const phone = str(b.phone).replace(/[\s\-\.]/g, ''); if (!phone) missing.push('phone');
const date = str(b.date); if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) missing.push('date (YYYY-MM-DD)');
let time = str(b.time); if (/^\d{1}:\d{2}$/.test(time)) time = '0' + time;
if (!/^\d{2}:\d{2}$/.test(time)) missing.push('time (HH:MM, 24h)');
const doctor = str(b.doctor), city = str(b.city), location = str(b.location);
if (!doctor && !location && !city) missing.push('doctor or location');
