const problem = str(b.problem);
const conversation_id = str(b.conversation_id || b.idempotency_key) || 'anon';
if (missing.length) {
  return [{ json: { _error: true, success: false, error: 'missing_fields', missing,
    hint: 'Ask the caller for the missing details, then call this tool again.' } }];
}

// ---- phone read-back gate (server-side) ----
// The agent must read the number back digit by digit and get the caller's yes before this call.
// It reports that with phone_confirmed=true. A call without it is refused with a read-back instruction;
// a call that flips the flag less than 5 s after the refusal is refused again (no real read-back could fit).
{
  const sd = $getWorkflowStaticData('global'); sd.phoneGate = sd.phoneGate || {};
  const now = Date.now();
  for (const k of Object.keys(sd.phoneGate)) if (now - sd.phoneGate[k] > 2 * 3600 * 1000) delete sd.phoneGate[k];
  const conv = str(b.conversation_id || b.idempotency_key) || 'anon';
  const gateKey = conv + '|' + phone;
  const confirmed = b.phone_confirmed === true || String(b.phone_confirmed).toLowerCase() === 'true';
  const firstRefusal = sd.phoneGate[gateKey];
  if (!confirmed || (firstRefusal && now - firstRefusal < 5000)) {
    if (!firstRefusal) sd.phoneGate[gateKey] = now;
    const d = phone.split('');
    const groups = [];
    for (let i = 0; i < d.length; i += 3) groups.push(d.slice(i, i + 3).join(', '));
    return [{ json: { _error: true, success: false, error: 'confirm_phone_first', phone,
      read_back: groups.join(' — '),
      message: 'Nothing was done yet. First read this phone number back to the caller digit by digit, ask whether it is correct, and END your turn. Only after the caller answers yes, call this tool again with exactly the same details and phone_confirmed set to true. If the caller corrects the number, call again with the corrected number and phone_confirmed true after they confirm it.' } }];
  }
}

// ---- slot acceptance gate (server-side) ----
// The agent must have offered this exact day+time and the caller must have accepted it (slot_accepted=true).
{
  const accepted = b.slot_accepted === true || String(b.slot_accepted).toLowerCase() === 'true';
  if (!accepted) {
    return [{ json: { _error: true, success: false, error: 'offer_slot_first', date, time,
      message: 'Nothing was booked. First offer this day and time to the caller (weekday, date, hour, doctor, branch), ask whether it suits, and END your turn. Only after the caller accepts, call this tool again with the same details and slot_accepted set to true.' } }];
  }
}
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Bucharest' });
if (date < today) {
  return [{ json: { _error: true, success: false, error: 'date_in_past', requested_date: date,
    today } }];
}
// ---- remember the confirmed number for this call ----
// Once a caller has dictated a number and confirmed the read-back, no later step in the same call
// should make them dictate it again. The number is kept against the conversation id so log_request
// can recover it server-side instead of relying on the agent to remember not to ask.
{
  const sd = $getWorkflowStaticData('global'); sd.confirmedPhone = sd.confirmedPhone || {};
  const now = Date.now();
  for (const k of Object.keys(sd.confirmedPhone)) if (now - sd.confirmedPhone[k].ts > 6 * 3600 * 1000) delete sd.confirmedPhone[k];
  const conv = str(b.conversation_id || b.idempotency_key);
  if (conv) sd.confirmedPhone[conv] = { phone, ts: now };
