return [{ json: { full_name, phone, email, date, time, doctor, city, location,
  problem, conversation_id } }];

const q = $('BOOK Validate Input').first().json;
const cals = $('BOOK Match Calendars').all().map(i => i.json);
const resps = $input.all().map(i => i.json);
let apiErrors = 0, dayMisses = 0;
const altDays = [], freeThatDay = [], matches = [];
for (let i = 0; i < resps.length; i++) {
  const r = resps[i]; const cal = cals[i] || {};
  if (r.statusCode !== 200 || !r.body || !r.body.Records) { apiErrors++; continue; }
  const day = (r.body.Records || []).find(x => x.wday === q.date);
  if (!day) {
    dayMisses++;
    for (const x of (r.body.Records || []).slice(0, 3)) altDays.push({ date: x.wday, doctor: cal.doctor, sample_times: (x.free_timespace || []).slice(0, 5).map(s => s.slot) });
    continue;
  }
  const slot = (day.free_timespace || []).find(s => s.slot === q.time);
  if (slot) matches.push({ slotid: slot.slotid, date: q.date, time: q.time, calendarid: cal.calendarid, doctor: cal.doctor, service: cal.service || '', location: cal.location });
  else for (const s of (day.free_timespace || [])) freeThatDay.push({ time: s.slot, doctor: cal.doctor });
}
if (matches.length) return [{ json: matches[0] }];
if (apiErrors === resps.length) {
  return [{ json: { _error: true, success: false, error: 'evolvo_api_error', step: 'get_work_days' } }];
}
if (dayMisses === resps.length - apiErrors) {
  altDays.sort((a, b) => a.date.localeCompare(b.date));
  return [{ json: { _error: true, success: false, error: 'date_not_available',
    requested_date: q.date, alternative_days: altDays.slice(0, 3),
    hint: 'Offer the caller one of the alternative days.' } }];
}
freeThatDay.sort((a, b) => a.time.localeCompare(b.time));
return [{ json: { _error: true, success: false, error: 'time_not_available',
  requested: q.date + ' ' + q.time,
  free_times_that_day: freeThatDay.slice(0, 12),
  hint: 'Offer the caller one of the free times (say the doctor too).' } }];
